#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Complex {
    pub re: i32,
    pub im: i32,
}

pub fn real_if_close(arr: Vec<Complex>, tol: i32) -> Vec<Complex> {
    // Assumption: tol is strictly positive.
    debug_assert!(tol > 0);

    const MACHINE_EPS: i32 = 2;

    // Compute threshold in i64 to avoid overflow: tol * MACHINE_EPS.
    let threshold: i64 = (tol as i64) * (MACHINE_EPS as i64);

    // Check if all imaginary parts are "close to zero".
    let all_close = arr.iter().all(|c| (c.im as i64).abs() <= threshold);

    if all_close {
        // Keep real parts identical; set imaginary parts to 0.
        arr.into_iter()
            .map(|c| Complex { re: c.re, im: 0 })
            .collect()
    } else {
        // Return unchanged.
        arr
    }
}